package org.rabochaya.projects;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.widget.*;import java.io.*;import java.util.concurrent.*;
/** Explicit SAF export; cancellation never removes cached source tiles. */
public final class CacheExportActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private Button save;private ProgressBar progress;private volatile boolean disposed,cancelled,running;private TileSource source;private MapComposition composition;private boolean snapshotFailed;
 protected void onCreate(Bundle b){super.onCreate(b);String failure="";long project=getIntent().getLongExtra("project",-1);try{if(b!=null&&b.getByteArray("composition")!=null)composition=MapComposition.decode(b.getByteArray("composition"),project);else if(b!=null&&b.containsKey("source_key")){String key=b.getString("source_key","");source=key.isEmpty()?new TileSource(b.getString("source_name"),b.getString("source_template"),b.getString("source_credit"),b.getInt("source_min"),b.getInt("source_max"),b.getBoolean("source_downloads")):MapCatalog.find(key);if(source==null)throw new IOException("Источник отсутствует в каталоге");}else if(!getIntent().getBooleanExtra("single_source",false)&&project>0&&MapCompositionSettings.active(this,project))composition=MapCompositionSettings.load(this,project).composition;else source=OnlineMapSettings.source(this);}catch(Exception e){snapshotFailed=true;failure="Не удалось открыть выбранный состав: "+e.getMessage();}
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,20,20,20);root.setBackgroundColor(0xff232d1d);setContentView(root);getWindow().setStatusBarColor(0xff1c2518);getWindow().setNavigationBarColor(0xff1c2518);ScrollView scroll=new ScrollView(this);status=new TextView(this);status.setTextColor(-1);status.setTextSize(17);status.setTypeface(WorkspaceUi.font(this));String title=composition!=null?"Композиция слоёв":source==null?"Карта недоступна":source.name;String description="Экспорт кеша · "+title+"\n\n";if(composition!=null){for(MapComposition.Layer layer:composition.layers)if(layer.visible&&layer.opacity>0)description+=layer.name+" · "+layer.opacity+"%\n";description+="\nПорядок, видимость и непрозрачность сохраняются в растровом снимке. ";}description+="Сохранённые тайлы объединяются в один MBTiles/TMS в EPSG:3857. Только имеющийся кеш и выбранные локальные подложки: новые тайлы из интернета не загружаются.\n\nДо 20 000 тайлов и 512 МиБ. Метки и вложения в файл карты не входят. Совместимость с конкретной сторонней программой нужно проверить.";status.setText(snapshotFailed?failure:description);scroll.addView(status);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,-2));
  save=new Button(this);save.setText("Сохранить MBTiles");save.setAllCaps(false);save.setTypeface(WorkspaceUi.font(this));save.setEnabled(!snapshotFailed);root.addView(save);save.setOnClickListener(v->{if(running||snapshotFailed)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Рабочая-карта-кеш.mbtiles").putExtra(Intent.EXTRA_LOCAL_ONLY,true);try{startActivityForResult(i,4401);}catch(ActivityNotFoundException e){status.setText("На устройстве нет файлового диалога Android");}});
  Button cancel=new Button(this);cancel.setText("Отмена / назад");cancel.setAllCaps(false);cancel.setTypeface(WorkspaceUi.font(this));root.addView(cancel);cancel.setOnClickListener(v->onBackPressed());
 }
 protected void onSaveInstanceState(Bundle b){try{if(composition!=null)b.putByteArray("composition",composition.encode());else if(source!=null){String key="";for(MapCatalog.Entry e:MapCatalog.entries())if(e.source.id.equals(source.id)){key=e.key;break;}b.putString("source_key",key);b.putString("source_name",source.name);b.putString("source_template",source.template);b.putString("source_credit",source.attribution);b.putInt("source_min",source.minZoom);b.putInt("source_max",source.maxZoom);b.putBoolean("source_downloads",source.downloads);}}catch(IOException e){snapshotFailed=true;}super.onSaveInstanceState(b);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(!snapshotFailed&&request==4401&&result==RESULT_OK&&data!=null&&data.getData()!=null)export(data.getData());}
 private void export(final Uri uri){if(running)return;running=true;cancelled=false;save.setEnabled(false);status.setText("Подготовка снимка кеша…");worker.execute(()->{File tmp=null;String message;boolean copied=false,destinationOpened=false;try{
   tmp=File.createTempFile("map-cache-export-",".mbtiles",getCacheDir());CacheExport.Progress update=(done,total)->{checkCancelled();if(done%10==0||done==total)runOnUiThread(()->{if(!disposed){progress.setMax(total);progress.setProgress(done);status.setText("Экспорт тайлов: "+done+" / "+total);}});};int count=composition==null?CacheExport.write(this,source,tmp,update):CompositionCacheExport.write(this,composition,tmp,update);
   checkCancelled();destinationOpened=true;try(InputStream in=new FileInputStream(tmp);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Не удалось открыть файл назначения");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){checkCancelled();out.write(buffer,0,n);}out.flush();}checkCancelled();copied=true;message="Сохранено: "+count+" тайлов в одном MBTiles. Исходный кеш сохранён.";
  }catch(Exception e){message=cancelled?"Экспорт отменён. Исходный кеш сохранён.":"Экспорт не завершён: "+e.getMessage();if(destinationOpened&&!copied)message+=" Файл назначения мог быть записан частично. Повторите экспорт в новый файл.";}finally{if(tmp!=null)tmp.delete();}
  final String text=message;runOnUiThread(()->{running=false;if(!disposed){status.setText(text);save.setEnabled(true);}});
 });}
 private void checkCancelled()throws IOException{if(cancelled||disposed)throw new IOException("Экспорт отменён");}
 public void onBackPressed(){if(running){cancelled=true;status.setText("Отмена экспорта…");}else super.onBackPressed();}
 protected void onStop(){if(running)cancelled=true;super.onStop();}
 protected void onDestroy(){disposed=true;cancelled=true;worker.shutdown();super.onDestroy();}
}
